 auto owner=h.find("android/content/Context"),activity=h.find("android/app/Activity");auto field=h.run("display_service_field",{h.host.EnvAddress(),owner,reinterpret_cast<addr_t>("Ljava/lang/String;")});check(field&&h.host.PendingException().empty(),"actual GetStaticFieldID144 resolves exact reached field");
