 auto old_field=h.call(144,owner,reinterpret_cast<addr_t>("LOCATION_SERVICE"),reinterpret_cast<addr_t>("Ljava/lang/String;"));auto old_value=h.call(145,owner,old_field);check(old_field&&old_field!=field&&h.host.StringValue(old_value)==std::optional<std::u16string>(u"location"),"existing LOCATION_SERVICE remains a distinct exact constant");h.host.DeleteLocalReference(old_value);
 auto global=h.host.NewGlobalReference(value),weak=h.call(226,value);h.host.DeleteLocalReference(value);
 for(const char *name:{"android/content/Context","android/app/Activity",kLaunchActivity})for(unsigned n=0;n<4;++n){auto result=h.run("display_service_lookup",{h.host.EnvAddress(),reinterpret_cast<addr_t>(name)});check(result!=global&&h.call(232,result)==1&&h.call(24,result,global)&&h.host.StringValue(result)==std::optional<std::u16string>(u"display"),"each real NDK lookup returns a fresh local with stable static String identity/content");h.host.DeleteLocalReference(result);}
 // The existing setter accepts another reference to the exact same object;
